import net.neoforged.neoforge.items.wrapper.RecipeWrapper;

public class SequencedAssemblyRecipe implements Recipe<RecipeWrapper> {
	protected SequencedAssemblyRecipeSerializer serializer;

	protected Ingredient ingredient;
	protected List<SequencedRecipe<?>> sequence;
	protected int loops;
	protected ProcessingOutput transitionalItem;

	public final List<ProcessingOutput> resultPool;

	public SequencedAssemblyRecipe(SequencedAssemblyRecipeSerializer serializer) {
		this.serializer = serializer;
		sequence = new ArrayList<>();
		resultPool = new ArrayList<>();
		loops = 5;
	}

	public static <I extends RecipeInput, R extends ProcessingRecipe<I, ?>> Optional<RecipeHolder<R>> getRecipe(Level world, I inv,
																												RecipeType<R> type, Class<R> recipeClass) {
		return getRecipe(world, inv, type, recipeClass, r -> r.value().matches(inv, world));
	}

	public static <I extends RecipeInput, R extends ProcessingRecipe<I, ?>> Optional<RecipeHolder<R>> getRecipe(Level world, I inv,
																												RecipeType<R> type, Class<R> recipeClass, Predicate<? super RecipeHolder<R>> recipeFilter) {
		List<RecipeHolder<R>> list = getRecipes(world, inv.getItem(0), type, recipeClass, recipeFilter);

		if (!list.isEmpty()) {
			return Optional.of(list.getFirst());
		} else {
			return Optional.empty();
		}
	}

	public static <R extends ProcessingRecipe<?, ?>> Optional<RecipeHolder<R>> getRecipe(Level level, ItemStack item,
																						 RecipeType<R> type, Class<R> recipeClass) {
		List<RecipeHolder<SequencedAssemblyRecipe>> all = level.getRecipeManager()
			.getAllRecipesFor(AllRecipeTypes.SEQUENCED_ASSEMBLY.getType());
		for (RecipeHolder<SequencedAssemblyRecipe> sequencedAssemblyRecipe : all) {
			if (!sequencedAssemblyRecipe.value().appliesTo(sequencedAssemblyRecipe.id(), item))
				continue;
			SequencedRecipe<?> nextRecipe = sequencedAssemblyRecipe.value().getNextRecipe(item);
			ProcessingRecipe<?, ?> recipe = nextRecipe.getRecipe();
			if (recipe.getType() != type || !recipeClass.isInstance(recipe))
				continue;
			recipe.enforceNextResult(() -> sequencedAssemblyRecipe.value().advance(sequencedAssemblyRecipe.id(), item, level.random));
			return Optional.of(new RecipeHolder<>(sequencedAssemblyRecipe.id(), recipeClass.cast(recipe)));
		}
		return Optional.empty();
	}

	public static <R extends ProcessingRecipe<?, ?>> List<RecipeHolder<R>> getRecipes(Level level, ItemStack item, RecipeType<R> type, Class<R> recipeClass, Predicate<? super RecipeHolder<R>> recipeFilter) {
		List<RecipeHolder<SequencedAssemblyRecipe>> all = level.getRecipeManager()
			.getAllRecipesFor(AllRecipeTypes.SEQUENCED_ASSEMBLY.getType());

		List<RecipeHolder<R>> result = new ArrayList<>();

		for (RecipeHolder<SequencedAssemblyRecipe> holder : all) {
			if (holder.value().appliesTo(holder.id(), item)) {
				ProcessingRecipe<?, ?> recipe = holder.value().getNextRecipe(item).getRecipe();

				if (recipe.getType() == type && recipeClass.isInstance(recipe)) {
					recipe.enforceNextResult(() -> holder.value().advance(holder.id(), item, level.random));
					R castedRecipe = recipeClass.cast(recipe);
					RecipeHolder<R> h = new RecipeHolder<>(holder.id(), castedRecipe);
					if (recipeFilter.test(h))
						result.add(h);
				}
			}
		}

		return result;
	}

	private ItemStack advance(ResourceLocation id, ItemStack input, RandomSource random) {
		int step = getStep(input);
		if ((step + 1) / sequence.size() >= loops)
			return rollResult(random);

		ItemStack advancedItem = getTransitionalItem().copyWithCount(1);
		SequencedAssembly sequencedAssembly = new SequencedAssembly(
			id,
			step + 1,
			(step + 1f) / (sequence.size() * loops)
		);
		advancedItem.set(AllDataComponents.SEQUENCED_ASSEMBLY, sequencedAssembly);
		return advancedItem;
	}

	public int getLoops() {
		return loops;
	}

	private ItemStack rollResult(RandomSource random) {
		float totalWeight = 0;
		for (ProcessingOutput entry : resultPool)
			totalWeight += entry.getChance();
		float number = random.nextFloat() * totalWeight;
		for (ProcessingOutput entry : resultPool) {
			number -= entry.getChance();
			if (number < 0)
				return entry.getStack()
					.copy();
		}
		return ItemStack.EMPTY;
	}

	private boolean appliesTo(ResourceLocation id, ItemStack input) {
		// First, check if the item is already in the middle of a sequenced assembly recipe
		if (input.has(AllDataComponents.SEQUENCED_ASSEMBLY)) {
			//noinspection DataFlowIssue
			return getTransitionalItem().getItem() == input.getItem() && input
				.get(AllDataComponents.SEQUENCED_ASSEMBLY)
				.id().equals(id);
		}
		// Else it must be the first step in a new sequenced assembly recipe
		return ingredient.test(input);
	}

	private SequencedRecipe<?> getNextRecipe(ItemStack input) {
		return sequence.get(getStep(input) % sequence.size());
	}

	private int getStep(ItemStack input) {
		if (!input.has(AllDataComponents.SEQUENCED_ASSEMBLY))
			return 0;
		//noinspection DataFlowIssue
		return input.get(AllDataComponents.SEQUENCED_ASSEMBLY).step();
	}

	@Override
	public boolean matches(RecipeWrapper inv, Level level) {
		return false;
	}

	@Override
	public ItemStack assemble(RecipeWrapper input, HolderLookup.Provider registries) {
		return ItemStack.EMPTY;
	}

	@Override
	public boolean canCraftInDimensions(int width, int height) {
		return false;
	}

	@Override
	public ItemStack getResultItem(HolderLookup.Provider registries) {
		return resultPool.getFirst().getStack();
	}

	public float getOutputChance() {
		float totalWeight = 0;
		for (ProcessingOutput entry : resultPool)
			totalWeight += entry.getChance();
		return resultPool.getFirst().getChance() / totalWeight;
	}

	@Override
	public RecipeSerializer<?> getSerializer() {
		return serializer;
	}

	@Override
	public boolean isSpecial() {
		return true;
	}

	@Override
	public RecipeType<?> getType() {
		return AllRecipeTypes.SEQUENCED_ASSEMBLY.getType();
	}

	@OnlyIn(Dist.CLIENT)
	public static void addToTooltip(ItemTooltipEvent event) {
		ItemStack stack = event.getItemStack();
		if (!stack.has(AllDataComponents.SEQUENCED_ASSEMBLY))
			return;
		SequencedAssembly sequencedAssembly = stack.get(AllDataComponents.SEQUENCED_ASSEMBLY);
		@SuppressWarnings({"RedundantCast", "DataFlowIssue"}) // The java compiler thinks `byKey` returns an Optional<RecipeHolder<?>>
		Optional<RecipeHolder<? extends Recipe<?>>> optionalRecipe =
			(Optional<RecipeHolder<?>>) Minecraft.getInstance().level.getRecipeManager()
				.byKey(sequencedAssembly.id());
		if (optionalRecipe.isEmpty())
			return;
		Recipe<?> recipe = optionalRecipe.get().value();
		if (!(recipe instanceof SequencedAssemblyRecipe sequencedAssemblyRecipe))
			return;

		int length = sequencedAssemblyRecipe.sequence.size();
		int step = sequencedAssemblyRecipe.getStep(stack);
		int total = length * sequencedAssemblyRecipe.loops;
		List<Component> tooltip = event.getToolTip();
		tooltip.add(CommonComponents.EMPTY);
		tooltip.add(CreateLang.translateDirect("recipe.sequenced_assembly")
			.withStyle(ChatFormatting.GRAY));
		tooltip.add(CreateLang.translateDirect("recipe.assembly.progress", step, total)
			.withStyle(ChatFormatting.DARK_GRAY));

		int remaining = total - step;
		for (int i = 0; i < length; i++) {
			if (i >= remaining)
				break;
			SequencedRecipe<?> sequencedRecipe = sequencedAssemblyRecipe.sequence.get((i + step) % length);
			Component textComponent = sequencedRecipe.getAsAssemblyRecipe()
				.getDescriptionForAssembly();
			if (i == 0)
				tooltip.add(CreateLang.translateDirect("recipe.assembly.next", textComponent)
					.withStyle(ChatFormatting.AQUA));
			else {
				tooltip.add(Component.literal("-> ").append(textComponent)
					.withStyle(ChatFormatting.DARK_AQUA));
			}
		}

	}

	public Ingredient getIngredient() {
		return ingredient;
	}

	public List<SequencedRecipe<?>> getSequence() {
		return sequence;
	}

	public ItemStack getTransitionalItem() {
		return transitionalItem.getStack();
	}

	public record SequencedAssembly(ResourceLocation id, int step, float progress) {
		public static final Codec<SequencedAssembly> CODEC = RecordCodecBuilder.create(i -> i.group(
			ResourceLocation.CODEC.fieldOf("id").forGetter(SequencedAssembly::id),
			Codec.INT.fieldOf("step").forGetter(SequencedAssembly::step),
			Codec.FLOAT.fieldOf("progress").forGetter(SequencedAssembly::progress)
		).apply(i, SequencedAssembly::new));

		public static final StreamCodec<ByteBuf, SequencedAssembly> STREAM_CODEC = StreamCodec.composite(
			ResourceLocation.STREAM_CODEC, SequencedAssembly::id,
			ByteBufCodecs.INT, SequencedAssembly::step,
			ByteBufCodecs.FLOAT, SequencedAssembly::progress,
			SequencedAssembly::new
		);
	}
}

package com.simibubi.create.foundation.mixin.datafixer;

import java.util.List;
import java.util.Map;

import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

import com.llamalad7.mixinextras.sugar.Local;
import com.mojang.datafixers.DSL;
import com.mojang.datafixers.DataFix;
import com.mojang.datafixers.OpticFinder;
import com.mojang.datafixers.TypeRewriteRule;
import com.mojang.datafixers.schemas.Schema;
import com.simibubi.create.foundation.utility.DataFixerHelper;

import net.minecraft.util.datafix.fixes.BlockPosFormatAndRenamesFix;

@Mixin(BlockPosFormatAndRenamesFix.class)
public abstract class BlockPosFormatAndRenamesFixMixin extends DataFix {
	private BlockPosFormatAndRenamesFixMixin(Schema outputSchema, boolean changesType) {
		super(outputSchema, changesType);
	}

	@Shadow
	protected abstract TypeRewriteRule createEntityFixer(DSL.TypeReference reference, String entityId, Map<String, String> renames);

	@Inject(method = "makeRule", at = @At(value = "INVOKE", target = "Ljava/util/List;add(Ljava/lang/Object;)Z", ordinal = 0))
	private void create$addFixers(CallbackInfoReturnable<TypeRewriteRule> cir, @Local List<TypeRewriteRule> output) {
		for (DataFixerHelper.BlockPosFixer fixer : DataFixerHelper.BLOCK_POS_FIXERS_VIEW) {
			DSL.TypeReference ref = fixer.reference();
			String id = fixer.id();

			TypeRewriteRule rule;

			if (fixer.customFixer() != null) {
				OpticFinder<?> opticfinder = DSL.namedChoice(id, this.getInputSchema().getChoiceType(ref, id));
				rule = fixTypeEverywhereTyped("BlockPos format for " + id + " (" + ref.typeName() + ")",
						getInputSchema().getType(ref),
						typed -> typed.updateTyped(opticfinder, data ->
									data.update(DSL.remainderFinder(), dynamic ->
										fixer.customFixer().apply(dynamic)
									)
								)
				);
			} else {
				rule = createEntityFixer(ref, id, fixer.renames());
			}

			output.add(rule);
		}
	}
}

package com.simibubi.create.foundation.mixin.datafixer;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Stream;

import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Unique;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

import com.mojang.serialization.Dynamic;
import com.simibubi.create.content.equipment.clipboard.ClipboardOverrides;
import com.simibubi.create.content.equipment.zapper.PlacementPatterns;
import com.simibubi.create.content.equipment.zapper.terrainzapper.PlacementOptions;
import com.simibubi.create.content.equipment.zapper.terrainzapper.TerrainBrushes;
import com.simibubi.create.content.equipment.zapper.terrainzapper.TerrainTools;
import com.simibubi.create.content.logistics.filter.AttributeFilterWhitelistMode;

import net.minecraft.util.StringRepresentable;
import net.minecraft.util.datafix.fixes.ItemStackComponentizationFix;
import net.minecraft.world.item.DyeColor;

@Mixin(ItemStackComponentizationFix.class)
public class ItemStackComponentizationFixMixin {
	@Inject(method = "fixItemStack", at = @At("TAIL"))
	private static void create$fixItemsAndTranslateNBTIntoComponents(ItemStackComponentizationFix.ItemStackData stack, Dynamic<?> dynamic, CallbackInfo ci) {
		// create:symmetry_wand is skipped since it doesn't have anything important
		stack.removeTag("SequencedAssembly").result().ifPresent(d -> {
			float progress = d.get("Progress").asFloat(0);
			String id = d.get("id").asString().getOrThrow();
			int step = d.get("Step").asInt(1);

			Dynamic<?> seqDynamic = dynamic.emptyMap();
			seqDynamic = seqDynamic.set("progress", dynamic.createFloat(progress));
			seqDynamic = seqDynamic.set("step", dynamic.createInt(step));
			seqDynamic = seqDynamic.set("id", dynamic.createString(id));

			stack.setComponent("create:sequenced_assembly", seqDynamic);
		});

		if (stack.is("create:copper_backtank") || stack.is("create:netherite_backtank")) {
			stack.moveTagToComponent("Air", "create:banktank_air");
		}

		if (stack.is("create:belt_connector")) {
			stack.moveTagToComponent("FirstPulley", "create:belt_first_shaft");
		}

		if (stack.is("create:handheld_worldshaper")) {
			create$moveTagToEnumComponent(stack, "Pattern", "create:placement_pattern", PlacementPatterns.class);
			create$moveTagToEnumComponent(stack, "Brush", "create:shaper_brush", TerrainBrushes.class);
			stack.moveTagToComponent("BrushParams", "create:shaper_brush_params");
			create$moveTagToEnumComponent(stack, "Placement", "create:shaper_placement_options", PlacementOptions.class);
			create$moveTagToEnumComponent(stack, "Tool", "create:shaper_tool", TerrainTools.class);
			stack.moveTagToComponent("BlockUsed", "create:shaper_block_used");
			stack.moveTagToComponent("_Swap", "create:shaper_swap");
			stack.moveTagToComponent("BlockData", "create:shaper_block_data");
		}

		if (stack.is("create:filter")) {
			create$moveItemStackHandlerToItemContainerContents(stack, dynamic, "Items", "create:filter_items");
			stack.moveTagToComponent("RespectNBT", "create:filter_items_respect_nbt");
			stack.moveTagToComponent("Blacklist", "create:filter_items_blacklist");
		}

		// MatchedAttribute's won't be fixed, it's not really possible to write a fixer for that
		if (stack.is("create:attribute_filter")) {
			create$moveTagToEnumComponent(stack, "WhitelistMode", "create:filter_items", AttributeFilterWhitelistMode.class);
		}

		if (stack.is("create:clipboard")) {
			create$moveTagToEnumComponent(stack, "Type", "create:clipboard_type", ClipboardOverrides.ClipboardType.class);
			// Moves it from a boolean to a Unit (instance is the enum name)
			stack.removeTag("Readonly").result().ifPresent(itemDynamic -> {
				stack.setComponent("create:clipboard_read_only", itemDynamic.emptyMap().createString("instance"));
			});
			stack.moveTagToComponent("CopiedValues", "create:clipboard_copied_values");
			stack.moveTagToComponent("Pages", "create:clipboard_pages");
		}

		if (stack.is("create:track")) {
			stack.moveTagToComponent("ConnectingFrom", "create:track_connecting_from");
			stack.moveTagToComponent("ExtendCurve", "create:track_extended_curve");
		}

		if (stack.is(Set.of("create:track_station", "create:track_signal", "create:track_observer"))) {
			stack.moveTagToComponent("SelectedPos", "create:track_targeting_item_selected_pos");
			stack.moveTagToComponent("SelectedDirection", "create:track_targeting_item_selected_direction");
			stack.moveTagToComponent("Bezier", "track_targeting_item_bezier");
		}

		if (stack.is("create:schematic")) {
			stack.moveTagToComponent("Deployed", "create:schematic_deployed");
			stack.moveTagToComponent("Owner", "create:schematic_owner");
			stack.moveTagToComponent("File", "create:schematic_file");
			stack.moveTagToComponent("Anchor", "create:schematic_anchor");
			stack.moveTagToComponent("Rotation", "create:schematic_rotation");
			stack.moveTagToComponent("Mirror", "create:schematic_mirror");
			stack.moveTagToComponent("Bounds", "create:schematic_bounds");
		}

		if (stack.is("create:chromatic_compound")) {
			stack.moveTagToComponent("CollectingLight", "create:chromatic_compound_collecting_light");
		}

		if (stack.is(Set.of("create:sand_paper", "create:red_sand_paper"))) {
			stack.moveTagToComponent("Polishing", "create:sand_paper_polishing");
		}

		if (stack.is("create:minecart_contraption")) {
			stack.moveTagToComponent("Contraption", "create:minecart_contraption_data");
		}

		if (stack.is("create:linked_controller")) {
			create$moveItemStackHandlerToItemContainerContents(stack, dynamic, "Items", "create:linked_controller_items");
		}

		if (create$isCheckWithDyeColors(stack, "create:{}_toolbox")) {
			create$moveItemStackHandlerToItemContainerContents(stack, dynamic, "Inventory", "create:toolbox_inventory");
			stack.moveTagToComponent("UniqueId", "create:toolbox_uuid");
		}

		if (stack.is("create:schedule")) {
			stack.moveTagToComponent("Schedule", "create:train_schedule");
		}

		if (stack.is("create:display_link")) {
			stack.moveTagToComponent("SelectedPos", "create:display_link_selected_pos");
		}

		if (stack.is("create:schematicannon")) {
			stack.moveTagToComponent("BlockEntityTag.Options", "create:schematicannon_options");
		}
	}

	@Unique
	private static boolean create$isCheckWithDyeColors(ItemStackComponentizationFix.ItemStackData stack, String template) {
		Set<String> ids = new HashSet<>();
		for (DyeColor dyeColor : DyeColor.values()) {
			ids.add(template.replace("{}", dyeColor.getName()));
		}
		return stack.is(ids);
	}

	/**
	 * Converts an int nbt tag storing an enum via it's ordinal to a component storing the enum by using {@link StringRepresentable#fromValues}
	 *
	 * @param stack {@link ItemStackComponentizationFix.ItemStackData}
	 * @param key {@link String} The NBT Tag key that holds the int value
	 * @param component {@link String} The data component type ID
	 * @param enumClass The class holding the enum values
	 */
	@Unique
	private static <T extends Enum<?>> void create$moveTagToEnumComponent(ItemStackComponentizationFix.ItemStackData stack, String key, String component, Class<T> enumClass) {
		if (!enumClass.isEnum())
			throw new IllegalArgumentException("moveTagToEnumComponent must be called with a enum class!");

		T[] enumConstants = enumClass.getEnumConstants();

		stack.removeTag(key).result().ifPresent(itemDynamic -> {
			T enumConstant = enumConstants[itemDynamic.asInt(0)];
			String enumConstantName;

			if (enumConstant instanceof StringRepresentable stringRepresentable) {
				enumConstantName = stringRepresentable.getSerializedName();
			} else {
				throw new IllegalArgumentException("moveTagToEnumComponent must be called with a enum class that implements StringRepresentable!");
			}

			stack.setComponent(component, itemDynamic.emptyMap().createString(enumConstantName));
		});
	}

	@Unique
	private static void create$moveItemStackHandlerToItemContainerContents(ItemStackComponentizationFix.ItemStackData stack, Dynamic<?> dynamic, String key, String component) {
		try {
			stack.removeTag(key).result().ifPresent(itemDynamic -> {
				List<Dynamic<?>> list = new ArrayList<>();
				Stream<? extends Dynamic<?>> stream = itemDynamic.get("Items").asStream();
				stream.forEach(d -> {
					int slot = d.get("Slot").asInt(0);
					String id = d.get("id").asString().getOrThrow();
					int count = d.get("Count").asInt(1);

					Dynamic<?> dynamicMain = dynamic.emptyMap();
					Dynamic<?> dynamicItem = dynamic.emptyMap();

					dynamicItem = dynamicItem.set("count", dynamic.createInt(count));
					dynamicItem = dynamicItem.set("id", dynamic.createString(id));

					dynamicMain = dynamicMain.set("item", dynamicItem);
					dynamicMain = dynamicMain.set("slot", dynamic.createInt(slot));

					list.add(dynamicMain);
				});
				stack.setComponent(component, dynamic.createList(list.stream()));
			});
		} catch(Throwable ignored) {}
	}
}

